-- Function: public.fn_get_user_profile_security_details
-- Backup generated on 2026-10-25 20:33:44

CREATE OR REPLACE FUNCTION public.fn_get_user_profile_security_details(p_user_id uuid)  RETURNS TABLE(user_id uuid, display_name character varying, first_name character varying, last_name character varying, assigned_role_names character varying[], is_classroom_teacher boolean, is_parent boolean)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT         u.id as user_id,         u.display_name::VARCHAR,         u.first_name::VARCHAR,         u.last_name::VARCHAR,         COALESCE((             SELECT array_agg(DISTINCT r.name::VARCHAR)             FROM (                 SELECT ur.role_id FROM user_roles ur JOIN roles r ON ur.role_id = r.id WHERE ur.user_id = p_user_id AND r.scope_type = 'Platform' AND r.tenant_id IS NULL                 UNION                 SELECT uor.role_id FROM user_organization_roles uor JOIN roles r ON uor.role_id = r.id WHERE uor.user_id = p_user_id             ) comb             JOIN roles r ON r.id = comb.role_id             WHERE r.name IS NOT NULL         ), ARRAY[]::VARCHAR[]) as assigned_role_names,         EXISTS(SELECT 1 FROM classroom_teachers ct WHERE ct.user_id = p_user_id) as is_classroom_teacher,         EXISTS(SELECT 1 FROM family_relationships fr WHERE fr.user_id = p_user_id) as is_parent     FROM users u     WHERE u.id = p_user_id; END; $function$ ;
